<script setup>
import {useRoute} from 'vue-router'
import {computed,defineAsyncComponent,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {api,Assets,thumb,waitJob} from '../api'
import TagPicker from '../components/TagPicker.vue'
import JobProgress from '../components/JobProgress.vue'
const AudioPlayer=defineAsyncComponent(()=>import('../viewers/AudioPlayer.vue'))
const LibraryImportPanel=defineAsyncComponent(()=>import('../components/LibraryImportPanel.vue'))
const route=useRoute()
const albums=ref({items:[],total:0}),tracks=ref({items:[],total:0}),offset=ref(0),albumOffset=ref(0),q=ref(''),albumId=ref(''),current=ref(null),editing=ref(null),error=ref(''),busy=ref(false),showImport=ref(false),waveform=ref(null),job=ref(null),autoNext=ref(false),choices=ref({world:[],character:[],work:[]}),choiceQ=ref(''),cross=ref(false)
const lifecycle=new AbortController();let timer;onBeforeUnmount(()=>{lifecycle.abort();clearTimeout(timer)})
const album=computed(()=>albums.value.items.find(a=>a.id===Number(albumId.value)))
const pool=ref({items:[],total:0}),poolQ=ref(''),poolOffset=ref(0),showPool=ref(false)
const category=['ASMR','Drama CD','广播剧','有声小说','游戏 OST','角色语音','音乐专辑','音频特典']
const fmt=s=>s==null?'未识别':`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(!lifecycle.signal.aborted)error.value=e.message}finally{if(!lifecycle.signal.aborted)busy.value=false}}
async function loadAlbums(){albums.value=await api.get('/api/audio/albums',{offset:albumOffset.value})}
async function loadTracks(){tracks.value=await api.get('/api/audio/tracks',{q:q.value,album_id:albumId.value||null,offset:offset.value})}
watch([q,albumId],()=>{offset.value=0;clearTimeout(timer);timer=setTimeout(()=>run(loadTracks),200)})
onMounted(()=>run(async()=>{await loadAlbums();await loadTracks();if(route.query.asset_id){const a=await Assets.get(Number(route.query.asset_id));if(a.kind==='audio')current.value=a;else throw new Error('此素材不是音轨')}}))
async function select(a,autoplay=false){autoNext.value=autoplay;current.value=await Assets.get(a.id);waveform.value=null;showImport.value=false}
async function next(){const i=tracks.value.items.findIndex(t=>t.id===current.value?.id);if(i>=0&&i+1<tracks.value.items.length)await select(tracks.value.items[i+1],true);else if(offset.value+50<tracks.value.total){offset.value+=50;await loadTracks();if(tracks.value.items[0])await select(tracks.value.items[0],true)}}
function newAlbum(a=null){editing.value=a?{...JSON.parse(JSON.stringify(a)),tag_ids:a.tags.map(t=>t.id)}:{title:'',category:'ASMR',world_id:null,work_id:null,character_id:null,cover_asset_id:null,favorite:false,stars:0,preference:0,notes:'',tag_ids:[]};loadChoices().catch(e=>error.value=e.message)}
async function loadChoices(){const entries=await Promise.all(['world','work','character'].map(kind=>api.get('/api/oc/choices',{kind,q:choiceQ.value})));choices.value={world:entries[0].items,work:entries[1].items,character:entries[2].items}}
async function save(){const {id,collection_id,tags,updated_at,...body}=editing.value;const value=id?await api.put(`/api/audio/albums/${id}?expected_updated_at=${encodeURIComponent(updated_at)}`,body):await api.post('/api/audio/albums',body);editing.value=null;await loadAlbums();albumId.value=value.id;await loadTracks()}
async function loadPool(){pool.value=await api.get('/api/audio/tracks',{q:poolQ.value,offset:poolOffset.value})}
async function add(a){await api.post(`/api/audio/albums/${album.value.id}/tracks`,{asset_ids:[a.id],allow_cross_scope:cross.value});await loadTracks()}
async function remove(a){await api.del(`/api/audio/albums/${album.value.id}/tracks/${a.id}`);await loadTracks()}
async function wave(){job.value=await api.post(`/api/audio/tracks/${current.value.id}/waveform`);await waitJob(job.value.id,j=>job.value=j,500,lifecycle.signal);if(lifecycle.signal.aborted)return;waveform.value=await api.get(`/api/audio/tracks/${current.value.id}/waveform`)}
</script>
<template><div class="grid"><p v-if="error" class="notice" role="alert">{{error}}</p><div class="audio-layout"><aside class="card grid"><div class="row"><b>Audio Library</b><button :disabled="busy" @click="newAlbum()">新建专辑</button></div><button :class="{primary:!albumId}" @click="albumId=''">全部音轨</button><button v-for="a in albums.items" :key="a.id" class="album" :class="{primary:albumId===a.id}" @click="albumId=a.id"><img v-if="a.cover_asset_id" :src="thumb(a.cover_asset_id)" alt="专辑封面" loading="lazy"/><span>{{a.title}}<small>{{a.category}} · {{a.stars}}星 · 喜爱{{a.preference}}</small></span></button><nav class="row"><button :disabled="busy||!albumOffset" @click="albumOffset-=30;run(loadAlbums)">上页专辑</button><span>{{albums.total}}集</span><button :disabled="busy||albumOffset+30>=albums.total" @click="albumOffset+=30;run(loadAlbums)">下页专辑</button></nav><p class="small muted">专辑和播放列表共用素材引用，不复制原件。未知作者和来源保持空白。</p></aside><section class="grid audio-content">
<section v-if="editing" class="card grid"><h2>{{editing.id?'编辑专辑':'建立专辑 / 播放列表'}}</h2><div class="grid cols-2"><label class="field">专辑标题<input v-model="editing.title" maxlength="200"/></label><label class="field">收藏类型<input v-model="editing.category" list="audio-types" maxlength="80"/><datalist id="audio-types"><option v-for="c in category" :key="c" :value="c"/></datalist></label><label class="field">星级<input v-model.number="editing.stars" type="number" min="0" max="5"/></label><label class="field">喜爱度<input v-model.number="editing.preference" type="number" min="0" max="100"/></label></div><label class="row"><input v-model="editing.favorite" type="checkbox"/>收藏</label><form class="row" @submit.prevent="run(loadChoices)"><input v-model="choiceQ" aria-label="搜索音频关联档案" placeholder="搜索世界观、作品和角色"/><button :disabled="busy">查找关联</button></form><div class="grid cols-2"><label class="field">世界观<select v-model="editing.world_id"><option :value="null">独立收藏</option><option v-for="w in choices.world" :key="w.id" :value="w.id">{{w.name}} · #{{w.id}}</option></select></label><label class="field">作品<select v-model="editing.work_id"><option :value="null">未指定</option><option v-for="w in choices.work" :key="w.id" :value="w.id">{{w.name}}</option></select></label><label class="field">关联角色<select v-model="editing.character_id"><option :value="null">未指定</option><option v-for="c in choices.character" :key="c.id" :value="c.id">{{c.name}} · #{{c.id}}</option></select></label><label class="field">封面素材ID（可为有封面的音轨）<input v-model.number="editing.cover_asset_id" type="number" min="1" @change="editing.cover_asset_id=editing.cover_asset_id||null"/></label></div><TagPicker v-model="editing.tag_ids"/><label class="field">专辑备注<textarea v-model="editing.notes" maxlength="30000"/></label><div class="row"><button class="primary" :disabled="busy||!editing.title.trim()" @click="run(save)">保存专辑</button><button @click="editing=null">取消编辑</button></div></section>
<header class="card grid"><div class="row"><h2>{{album?.title||'全部音轨'}}</h2><span class="spacer"/><button :disabled="busy" @click="run(loadTracks)">刷新音轨</button><button v-if="album" :disabled="busy" @click="newAlbum(album)">编辑专辑</button><button v-if="album" @click="showPool=!showPool;run(loadPool)">选择已有音轨</button><button v-if="album" @click="showImport=!showImport">{{showImport?'收起目录':'文件夹导入'}}</button><RouterLink v-if="album?.collection_id" class="btn" :to="`/collections?id=${album.collection_id}`">播放列表排序 / 通用收藏集</RouterLink></div><p v-if="album?.notes" class="notes">{{album.notes}}</p><label class="field">搜索音轨<input v-model="q" placeholder="标题、专辑、艺术家；分页读取"/></label><label v-if="album" class="row"><input v-model="cross" type="checkbox"/>允许本次引用不同作品/世界观音轨</label></header>
<section v-if="showPool&&album" class="card grid"><form class="row" @submit.prevent="poolOffset=0;run(loadPool)"><input v-model="poolQ" aria-label="搜索已有音轨"/><button>搜索素材库音轨</button></form><article v-for="a in pool.items" :key="a.id" class="row"><span>{{a.title}} · {{fmt(a.file.duration)}}</span><button :disabled="busy" @click="run(()=>add(a))">加入当前播放列表</button></article><div class="row"><button :disabled="busy||!poolOffset" @click="poolOffset-=50;run(loadPool)">前50项资料</button><span>{{pool.total}}轨</span><button :disabled="busy||poolOffset+50>=pool.total" @click="poolOffset+=50;run(loadPool)">后50项资料</button></div></section>
<LibraryImportPanel v-if="showImport&&album" :key="album.id" :collection-id="album.collection_id" :world-id="album.world_id" :work-id="album.work_id" audio-only @imported="run(loadTracks)"/>
<section v-if="current" class="card grid"><AudioPlayer :key="current.id" :asset="current" remember :autoplay="autoNext" @ended="run(next)"/><div class="row"><button :disabled="busy" @click="run(next)">下一曲</button><button :disabled="busy" @click="run(wave)">按需生成PCM WAV波形</button><button @click="current=null">关闭播放器并释放音轨</button><RouterLink class="btn" :to="`/assets?open=${current.id}`">素材档案</RouterLink></div><JobProgress :job="job"/><svg v-if="waveform?.available" class="wave" viewBox="0 0 512 80" role="img" aria-label="PCM采样波形"><path :d="waveform.peaks.map((v,i)=>`M${i} ${40-v*38}V${40+v*38}`).join(' ')" stroke="currentColor"/></svg><small v-if="waveform?.note">{{waveform.note}}</small></section>
<section class="card grid"><div class="tracks"><article v-for="a in tracks.items" :key="a.id" class="track"><img v-if="a.file.thumb" :src="thumb(a.id)" :alt="a.title+'封面'" loading="lazy"/><button class="track-title" @click="run(()=>select(a))"><b>{{a.file.track?'#'+a.file.track+' ':''}}{{a.title}}</b><small>{{[a.file.artist,a.file.album].filter(Boolean).join(' · ')||'专辑/艺术家未标注'}} · {{fmt(a.file.duration)}} · {{a.file.format||a.file.ext?.toUpperCase()}}</small></button><button v-if="album" :disabled="busy" @click="run(()=>remove(a))">移出播放列表</button></article></div><p v-if="!tracks.total" class="empty">暂无音轨。先建立专辑后扫描目录，或在素材库导入音频。无需AI/GPU。</p><nav class="row"><button :disabled="busy||!offset" @click="offset-=50;run(loadTracks)">上一页音轨</button><span>{{tracks.total}}轨 · 当前{{offset+1}}–{{Math.min(offset+50,tracks.total)}}</span><button :disabled="busy||offset+50>=tracks.total" @click="offset+=50;run(loadTracks)">下一页音轨</button></nav></section>
<p class="small muted">原生HTML音频按Range流式播放；不自动转码或上传。浏览器编码支持取决于容器与系统，有异常时保留原件并显示诊断。AI转录/摘要为后续可选功能。</p>
</section></div></div></template>
<style scoped>.audio-content{min-width:0;grid-template-columns:minmax(0,1fr)}.audio-content>.grid{min-width:0;grid-template-columns:minmax(0,1fr)}.audio-content :deep(button){white-space:normal;overflow-wrap:anywhere}.audio-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:14px;align-items:start}.audio-layout>*{min-width:0}.album{display:flex;text-align:left;align-items:center;gap:8px;white-space:normal}.album img{width:44px;height:44px;object-fit:cover}.album small,.track small{display:block;color:var(--muted);font-size:11px}.track{display:flex;gap:10px;align-items:center;border-bottom:1px solid var(--line);padding:9px 0;flex-wrap:wrap}.track img{width:44px;height:44px;object-fit:cover}.track-title{flex:1;min-width:160px;text-align:left;white-space:normal}.wave{width:100%;height:80px;color:var(--accent)}h2{margin:0}.notes{white-space:pre-wrap;overflow-wrap:anywhere}.row input[type=checkbox]{width:auto}@media(max-width:900px){.audio-layout{grid-template-columns:minmax(0,1fr)}}</style>
